*{box-sizing:border-box}
html,body,#root{margin:0;height:100%;background:#0d1822;color:#e7eef4;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:13px}
button{font:inherit;color:inherit;cursor:pointer}
.app{display:flex;flex-direction:column;height:100%;padding:10px;gap:10px}
.bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:#132230;border:1px solid #1f3346;border-radius:10px;padding:10px 12px}
.bar h1{font-size:16px;margin:0 8px 0 0;font-weight:600}
.pill{font-size:11px;padding:2px 8px;border-radius:999px;background:#2a2f14;color:#e6d27a;border:1px solid #5a5220}
.bar label{font-size:12px;color:#8ea3b5;display:flex;align-items:center;gap:6px}
.facts{font-size:12px;color:#8ea3b5}
.spacer{flex:1}
select,textarea{background:#0d1822;color:#e7eef4;border:1px solid #2a4258;border-radius:6px;padding:5px 8px;font:inherit}
.btn{border-radius:6px;padding:6px 14px;border:1px solid #2a4258;background:#132230}
.btn.primary{background:#3987e5;border-color:#3987e5;color:#fff;font-weight:600}
.btn.primary:disabled{opacity:.6;cursor:default}
.btn.ghost:hover{border-color:#3987e5}
.msgs{flex:1;min-height:0;overflow:auto;background:#132230;border:1px solid #1f3346;border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:12px}
.msg{display:flex}
.msg.user{justify-content:flex-end}
.bubble{max-width:70%;background:#1b3247;border:1px solid #2a4258;border-radius:12px 12px 2px 12px;padding:8px 12px;white-space:pre-wrap}
.card{max-width:92%;background:#0f1e2b;border:1px solid #1f3346;border-radius:12px 12px 12px 2px;padding:10px 12px;display:flex;flex-direction:column;gap:8px;min-width:0}
.answer{line-height:1.5}
.err{font-size:12px;color:#f08c8c;background:#2a1418;border:1px solid #5a2630;border-radius:6px;padding:6px 8px}
.tbl{overflow:auto;max-height:320px;border:1px solid #1f3346;border-radius:6px}
table{border-collapse:collapse;width:100%;font-size:12px}
th{position:sticky;top:0;background:#17293a;color:#8ea3b5;text-align:left;vertical-align:middle;font-weight:600;padding:6px 12px;white-space:nowrap}
td{padding:5px 12px;border-top:1px solid #182a3a;white-space:nowrap;text-align:left;vertical-align:middle}
td.n{font-variant-numeric:tabular-nums}
.note,.muted{font-size:11px;color:#6f8699}
.busy{flex-direction:row;align-items:center;color:#8ea3b5}
.spin{width:12px;height:12px;border:2px solid #2a4258;border-top-color:#3987e5;border-radius:50%;animation:sp 0.8s linear infinite}
@keyframes sp{to{transform:rotate(360deg)}}
.empty{margin:auto;text-align:center;max-width:640px;display:flex;flex-direction:column;gap:8px}
.empty .big{font-size:15px}
.empty .sub{color:#8ea3b5;font-size:12px}
.chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:6px}
.chip{background:#0d1822;border:1px solid #2a4258;border-radius:999px;padding:5px 12px;font-size:12px}
.chip:hover{border-color:#3987e5;color:#cfe2fb}
.composer{display:flex;gap:8px;align-items:stretch}
.composer textarea{flex:1;resize:none;padding:8px 10px}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:#0d1822}
::-webkit-scrollbar-thumb{background:#2a4258;border-radius:6px}

