// Ask UBM chat. Everything shown comes from the model (the page store); the
// widget only sends events out: onAsk, onPickCustomer, onClear.
var SUGGEST = [
  "Show total cost by month for the last 12 months",
  "Which 5 locations had the highest cost last year?",
  "Total cost by vendor this year",
  "Compare electricity usage this year vs last year by month",
  "Which month had the highest total cost?"
];
var M = {};
var lastCount = -1;

var root = document.getElementById("root");
root.innerHTML =
  '<div class="app">' +
  '<div class="bar"><h1>Ask UBM</h1><span class="pill">Demo · answers are AI-generated</span>' +
  '<label>Customer <select id="cust"></select></label><span class="facts" id="facts"></span>' +
  '<span class="spacer"></span><button class="btn ghost" id="clear">Clear chat</button></div>' +
  '<div class="msgs" id="msgs"></div>' +
  '<div class="composer"><textarea id="q" rows="2" placeholder="Ask a question about this customer\'s usage and cost…  (Enter to send, Shift+Enter for a new line)"></textarea>' +
  '<button class="btn primary" id="send">Ask</button></div>' +
  '</div>';

var $ = function (id) { return document.getElementById(id); };

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}

function fmt(v) {
  if (v == null || v === "") return '<span class="muted">—</span>';
  if (typeof v === "number" || (typeof v === "string" && /^-?\d+(\.\d+)?$/.test(v) && v.length < 16)) {
    return Number(v).toLocaleString(undefined, { maximumFractionDigits: 2 });
  }
  if (typeof v === "object") return esc(JSON.stringify(v));
  return esc(v);
}

function isNum(v) {
  return typeof v === "number" || (typeof v === "string" && /^-?\d+(\.\d+)?$/.test(v) && v.length < 16);
}

function table(m) {
  if (!m.columns || !m.columns.length) return "";
  var shown = (m.rows || []).slice(0, 50);
  var h = '<div class="tbl"><table><thead><tr>' +
    m.columns.map(function (c) { return "<th>" + esc(c) + "</th>"; }).join("") + "</tr></thead><tbody>";
  shown.forEach(function (r) {
    h += "<tr>" + m.columns.map(function (c) {
      return '<td class="' + (isNum(r[c]) ? "n" : "") + '">' + fmt(r[c]) + "</td>";
    }).join("") + "</tr>";
  });
  h += "</tbody></table></div>";
  var note = m.rowCount > shown.length ? "Showing " + shown.length + " of " + m.rowCount + " rows" : m.rowCount + (m.rowCount === 1 ? " row" : " rows");
  return h + '<div class="note">' + note + "</div>";
}

function renderBar() {
  var sel = $("cust");
  var list = M.customers || [];
  var want = String(M.customer || "");
  var html = list.map(function (c) {
    return '<option value="' + esc(c.id) + '"' + (String(c.id) === want ? " selected" : "") + ">" + esc(c.name) + "</option>";
  }).join("");
  if (!list.length) html = '<option value="' + esc(want) + '">' + (want ? "Customer " + esc(want) : "Loading…") + "</option>";
  if (sel.innerHTML !== html) sel.innerHTML = html;
  var f = M.facts || {};
  $("facts").textContent = f.first_month
    ? f.first_month + " to " + f.last_month + " · " + f.locations + " locations · " + (f.utilities || "")
    : "";
  var busy = !!M.busy;
  $("send").disabled = busy;
  $("send").textContent = busy ? "Working…" : "Ask";
}

function renderMsgs() {
  var msgs = M.messages || [];
  var box = $("msgs");
  var h = "";
  if (!msgs.length) {
    h += '<div class="empty"><div class="big">Ask anything about this customer\'s monthly usage and cost.</div>' +
      '<div class="sub">Answers come from the monthly usage report table. Try one of these:</div><div class="chips">' +
      SUGGEST.map(function (s) { return '<button class="chip" data-q="' + esc(s) + '">' + esc(s) + "</button>"; }).join("") +
      "</div></div>";
  }
  msgs.forEach(function (m, i) {
    if (m.role === "user") {
      h += '<div class="msg user"><div class="bubble">' + esc(m.text) + "</div></div>";
      return;
    }
    h += '<div class="msg ai"><div class="card">' +
      '<div class="answer">' + esc(m.text).replace(/\n/g, "<br>") + "</div>" +
      (m.error ? '<div class="err">' + esc(m.error) + "</div>" : "") +
      table(m) +
      "</div></div>";
  });
  if (M.busy) h += '<div class="msg ai"><div class="card busy"><span class="spin"></span>' + esc(M.busy) + "</div></div>";
  box.innerHTML = h;
  var count = msgs.length + (M.busy ? 0.5 : 0);
  if (count !== lastCount) { box.scrollTop = box.scrollHeight; lastCount = count; }
}

function render(model) {
  M = model || {};
  renderBar();
  renderMsgs();
}

function send(text) {
  var q = String(text == null ? $("q").value : text).trim();
  if (!q || M.busy) return;
  $("q").value = "";
  appsmith.triggerEvent("onAsk", { question: q });
}

$("send").addEventListener("click", function () { send(); });
$("q").addEventListener("keydown", function (e) {
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
});
$("clear").addEventListener("click", function () { appsmith.triggerEvent("onClear", {}); });
$("cust").addEventListener("change", function (e) {
  appsmith.triggerEvent("onPickCustomer", { pickedCustomer: e.target.value });
});
$("msgs").addEventListener("click", function (e) {
  var chip = e.target.closest(".chip");
  if (chip) send(chip.getAttribute("data-q"));
});

appsmith.onReady(function () {
  render(appsmith.model);
  appsmith.onModelChange(function (m) { render(m); });
});

